def solve(s):
    result = []

    for char in s:
        if 'a' <= char <= 'z':  # lowercase letter -> uppercase
            result.append(char.upper())
        elif 'A' <= char <= 'Z':  # uppercase letter -> lowercase
            result.append(char.lower())
        else:  # non-letter character or no letters at all (handled by logic below)
            pass

    if not any('a' <= c <= 'z' for c in s):
        return ''.join(reversed(result))

    return ''.join(result)


# Examples:
print(solve("1234"))      # "4321"
print(solve("ab"))        # "AB"
print(solve("#a@C"))      # "#A@c"

